// File: contracts/Snipingbot.sol


pragma solidity ^0.8.20;



contract SnipingBot {
    address public owner;
    IUniswapV2Router02 public uniswapRouter;

    event TokenSniped(address token, uint256 amount);
    event TokenSold(address token, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not contract owner");
        _;
    }

    constructor(address _router) {
        owner = msg.sender;
        uniswapRouter = IUniswapV2Router02(_router);
    }

    // This function swaps ETH for tokens.
    function snipeToken(address token, uint256 amountOutMin) external payable onlyOwner {
        // Declare a local memory array for the trade path.
        address[] memory path = new address[](2);
        address WETH = uniswapRouter.WETH();  // Get the WETH address from the router.
        path[0] = WETH;
        path[1] = token;

        uniswapRouter.swapExactETHForTokens{value: msg.value}(
            amountOutMin,
            path,
            address(this),
            block.timestamp + 300
        );

        emit TokenSniped(token, msg.value);
    }

    // This function swaps tokens back to ETH.
    // The 'percentage' parameter (in percent) determines the portion of tokens to sell.
    function sellToken(address token, uint256 percentage) external onlyOwner {
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to sell");

        uint256 amountToSell = (balance * percentage) / 100;
        require(amountToSell > 0, "Sell amount too low");

        // Approve the Uniswap router to spend the tokens.
        IERC20(token).approve(address(uniswapRouter), amountToSell);

        // Declare a local memory array for the trade path.
        address[] memory path = new address[](2);
        address WETH = uniswapRouter.WETH();
        path[0] = token;
        path[1] = WETH;

        uniswapRouter.swapExactTokensForETH(
            amountToSell,
            0,
            path,
            owner,
            block.timestamp + 300
        );

        emit TokenSold(token, amountToSell);
    }

    // Withdraw remaining ETH from the contract.
    function withdrawETH() external onlyOwner {
        payable(owner).transfer(address(this).balance);
    }

    // Withdraw any remaining tokens from the contract.
    function withdrawTokens(address token) external onlyOwner {
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");
        IERC20(token).transfer(owner, balance);
    }

    // Allow the contract to receive ETH.
    receive() external payable {}
}
